cleanup() {
    echo ""
    log_warn "Received interrupt signal"
    stop_dashboard
    stop_status_monitor
    save_state ${RETRY_COUNT:-0} "interrupted" 130
    log_info "State saved. Run again to resume."
    exit 130
}

