{
  "name": "todo-app-backend",
  "version": "1.0.0",
  "description": "Todo app backend with Express and SQLite",
  "main": "dist/index.js",
  "scripts": {
    "build": "tsc",
    "start": "node dist/index.js",
    "dev": "ts-node src/index.ts"
  },
  "dependencies": {
    "better-sqlite3": "^12.11.1",
    "cors": "^2.8.6",
    "express": "^4.18.2",
    "express-rate-limit": "^8.6.2"
  },
  "devDependencies": {
    "@types/better-sqlite3": "^7.6.13",
    "@types/cors": "^2.8.19",
    "@types/express": "^4.17.20",
    "@types/node": "^20.10.0",
    "ts-node": "^10.9.1",
    "typescript": "^5.3.0"
  },
  "overrides": {
    "diff": "4.0.4",
    "path-to-regexp": "0.1.13",
    "qs": "^6.15.0"
  }
}

import Database from 'better-sqlite3';
import path from 'path';

const dbPath = path.join(__dirname, '../../todos.db');

// Create database connection
let db: Database.Database | null = null;

export function getDatabase(): Database.Database {
  if (!db) {
    db = new Database(dbPath);
    db.pragma('journal_mode = WAL');
    console.log(`Connected to SQLite database at ${dbPath}`);
  }
  return db;
}

export function closeDatabase(): void {
  if (db) {
    db.close();
    db = null;
    console.log('Database connection closed');
  }
}

import { getDatabase } from './database';
import fs from 'fs';
import path from 'path';

function resolveSchemaPath(): string {
  const candidates = [
    path.join(__dirname, 'schema.sql'),
    path.join(__dirname, '../../src/db/schema.sql'),
  ];

  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) {
      return candidate;
    }
  }

  throw new Error(`Unable to locate schema.sql. Checked: ${candidates.join(', ')}`);
}

export function runMigrations(): void {
  try {
    const db = getDatabase();
    const schema = fs.readFileSync(resolveSchemaPath(), 'utf-8');

    // Execute the schema SQL
    db.exec(schema);

    console.log('Database migrations completed successfully');
  } catch (error) {
    console.error('Error running migrations:', error);
    throw error;
  }
}

export function initializeDatabase(): void {
  try {
    runMigrations();
    console.log('Database initialized and ready for use');
  } catch (error) {
    console.error('Failed to initialize database:', error);
    throw error;
  }
}

import express, { Express, Request, Response } from 'express';
import cors from 'cors';
import { initializeDatabase, closeDatabase } from './db';
import todosRouter from './routes/todos';

const app: Express = express();
app.disable('x-powered-by');
const PORT = process.env.PORT || 3001;

// Middleware
app.use(cors());
app.use(express.json());

// Initialize database on startup
try {
  initializeDatabase();
} catch (error) {
  console.error('Failed to initialize database:', error);
  process.exit(1);
}

// Routes
app.use('/api', todosRouter);

// Health check endpoint
app.get('/health', (_req: Request, res: Response) => {
  res.json({ status: 'ok', message: 'Backend server is running' });
});

// Start server
const server = app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('Shutting down gracefully...');
  closeDatabase();
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

export default app;

import { Router, Request, Response } from 'express';
import { rateLimit } from 'express-rate-limit';
import { getDatabase } from '../db';
import { ApiResponse, Todo } from '../types/index';

const router = Router();
const WINDOW_MS = 60_000;
const MAX_REQUESTS_PER_WINDOW = 60;
const db = getDatabase();

type TodoRow = Omit<Todo, 'completed'> & { completed: number };

function toTodo(row: TodoRow): Todo {
  return {
    ...row,
    completed: Boolean(row.completed),
  };
}

router.use(
  rateLimit({
    windowMs: WINDOW_MS,
    limit: MAX_REQUESTS_PER_WINDOW,
    standardHeaders: 'draft-8',
    legacyHeaders: false,
    message: { error: 'Too many requests. Please retry later.' },
  })
);

// GET /api/todos - Retrieve all todos
router.get('/todos', (_req: Request, res: Response): void => {
  try {
    const rows = db.prepare('SELECT * FROM todos ORDER BY createdAt DESC').all() as TodoRow[];
    const successResponse: ApiResponse<Todo[]> = {
      success: true,
      data: rows.map(toTodo),
    };
    res.json(successResponse);
  } catch {
    const errorResponse: ApiResponse<null> = {
      success: false,
      error: 'Database error',
    };
    res.status(500).json(errorResponse);
  }
});

// POST /api/todos - Create new todo
router.post('/todos', (req: Request, res: Response): void => {
  const { title } = req.body;

  // Validation
  if (!title || typeof title !== 'string' || title.trim() === '') {
    res.status(400).json({ error: 'Title is required and must be a non-empty string' });
    return;
  }

  const trimmedTitle = title.trim();
  const now = new Date().toISOString();

  try {
    const insertResult = db
      .prepare('INSERT INTO todos (title, completed, createdAt, updatedAt) VALUES (?, ?, ?, ?)')
      .run(trimmedTitle, 0, now, now);
    const row = db
      .prepare('SELECT * FROM todos WHERE id = ?')
      .get(insertResult.lastInsertRowid) as TodoRow | undefined;

    if (!row) {
      res.status(500).json({ error: 'Database error' });
      return;
    }

    const successResponse: ApiResponse<Todo> = {
      success: true,
      data: toTodo(row),
    };
    res.status(201).json(successResponse);
  } catch (error) {
    const details = error instanceof Error ? error.message : 'Unknown error';
    res.status(500).json({ error: 'Database error', details });
  }
});

// PATCH /api/todos/:id - Update todo completion status
router.patch('/todos/:id', (req: Request, res: Response): void => {
  const { id } = req.params;
  const { completed } = req.body;

  // Validation
  if (typeof completed !== 'boolean') {
    res.status(400).json({ error: 'Completed must be a boolean value' });
    return;
  }

  try {
    const row = db.prepare('SELECT * FROM todos WHERE id = ?').get(id) as TodoRow | undefined;
    if (!row) {
      res.status(404).json({ error: 'Todo not found' });
      return;
    }
    const now = new Date().toISOString();

    db.prepare('UPDATE todos SET completed = ?, updatedAt = ? WHERE id = ?').run(
      completed ? 1 : 0,
      now,
      id
    );
    const updatedRow = db.prepare('SELECT * FROM todos WHERE id = ?').get(id) as TodoRow | undefined;

    if (!updatedRow) {
      res.status(500).json({ error: 'Database error' });
      return;
    }

    const successResponse: ApiResponse<Todo> = {
      success: true,
      data: toTodo(updatedRow),
    };
    res.json(successResponse);
  } catch (error) {
    const details = error instanceof Error ? error.message : 'Unknown error';
    res.status(500).json({ error: 'Database error', details });
  }
});

// DELETE /api/todos/:id - Delete todo by id
router.delete('/todos/:id', (req: Request, res: Response): void => {
  const { id } = req.params;

  // Validation - check if id is a valid number
  if (!id || isNaN(Number(id))) {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }

  try {
    const row = db.prepare('SELECT * FROM todos WHERE id = ?').get(id) as TodoRow | undefined;
    if (!row) {
      res.status(404).json({ error: 'Todo not found' });
      return;
    }

    db.prepare('DELETE FROM todos WHERE id = ?').run(id);
    res.json({ message: 'Todo deleted successfully' });
  } catch (error) {
    const details = error instanceof Error ? error.message : 'Unknown error';
    res.status(500).json({ error: 'Database error', details });
  }
});

export default router;

// Todo item types
export interface Todo {
  id: number;
  title: string;
  description?: string;
  completed: boolean;
  createdAt: string;
  updatedAt: string;
}

// API response types
export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

// Request body types
export interface CreateTodoRequest {
  title: string;
  description?: string;
}

export interface UpdateTodoRequest {
  title?: string;
  description?: string;
  completed?: boolean;
}

// Database types
export interface DatabaseConfig {
  path: string;
  readonly?: boolean;
}

